import { useEffect, useMemo, useState } from "react";
import { Link, useLocation } from "wouter";
import {
  Activity, AlertTriangle, ArrowLeft, BarChart3, Check, ChevronRight, ClipboardList,
  Coins, Copy, FileText, LayoutDashboard, Loader2, MessageSquare, RefreshCw, Search,
  ShieldAlert, ShieldCheck, Ticket, TrendingUp, UserCog, Users, WalletCards, X,
} from "lucide-react";
