  const createScheduled = async () => { const problem = validate(scheduled); if (problem) { setError(problem); return; } const fallbackImage = (label: string) => `https://placehold.co/128x128/0f172a/ffffff/png?text=${encodeURIComponent(label.trim().slice(0, 3).toUpperCase() || "SB")}`; const safeImage = (value: string, label: string) => { const trimmed = value.trim(); if (!trimmed || trimmed.startsWith("data:image/")) return fallbackImage(label); return trimmed; }; const payload = { homeTeam: scheduled.homeTeam.trim(), awayTeam: scheduled.awayTeam.trim(), league: LEAGUE_API_VALUES[scheduled.league] || scheduled.league || undefined, sport: scheduled.sport, homeLogo: safeImage(scheduled.homeLogo, scheduled.homeTeam), awayLogo: safeImage(scheduled.awayLogo, scheduled.awayTeam), leagueLogo: safeImage(scheduled.leagueLogo, scheduled.league || "League"), featured: scheduled.featured, kickoffAt: new Date(scheduled.kickoffAt).toISOString(), finalScoreHome: Number(scheduled.scoreHome), finalScoreAway: Number(scheduled.scoreAway) }; console.groupCollapsed("[Scheduler UI] Submit automated match"); console.table({ homeTeam: payload.homeTeam, awayTeam: payload.awayTeam, league: payload.league ?? "(empty)", sport: payload.sport, kickoffAt: payload.kickoffAt, finalScoreHome: payload.finalScoreHome, finalScoreAway: payload.finalScoreAway, featured: payload.featured, homeLogo: payload.homeLogo, awayLogo: payload.awayLogo, leagueLogo: payload.leagueLogo }); console.info("Full scheduler payload is logged by [Scheduler] API diagnostics with image data redacted."); console.groupEnd(); setSaving(true); setError(""); setMessage(""); try { await api.adminMatchSchedule.create(payload); setMessage("Match scheduled successfully. Kickoff, goals, and full time will run automatically."); setScheduled(blank); setScheduleStep(1); await load(); } catch (e) { setError(e instanceof ApiError ? `Scheduler failed (${e.status}): ${e.message}` : e instanceof Error ? e.message : "Could not schedule match"); } finally { setSaving(false); } };
  const updateStatus = async (id: string, status: string) => { try { await api.adminMatches.updateStatus(id, { status }); setMessage(`Match status changed to ${status}.`); await load(); } catch (e) { setError(e instanceof Error ? e.message : "Status update failed"); } };
  const updateScore = async (row: Match) => { const home = window.prompt("Home score", String(row.scoreHome ?? 0)); const away = window.prompt("Away score", String(row.scoreAway ?? 0)); if (home === null || away === null) return; const h = Number(home), a = Number(away); if (!Number.isInteger(h) || !Number.isInteger(a) || h < 0 || a < 0) { setError("Scores must be non-negative whole numbers."); return; } try { await api.adminMatches.updateScore(row.id, { scoreHome: h, scoreAway: a, minutePlayed: row.minutePlayed }); setMessage("Match score updated."); await load(); } catch (e) { setError(e instanceof Error ? e.message : "Score update failed"); } };
  const inspectSchedule = async (id: string) => { setScheduleMatch(id); setScheduleDetails(null); try { setScheduleDetails(await api.adminMatchSchedule.getSchedule(id) as Row); } catch (e) { setError(e instanceof Error ? e.message : "Could not load schedule"); } };
